fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    // Create the first output matrix with y values
    let mut grid_y = vec![vec![0.0; cols]; rows];
    // Create the second output matrix with x values
    let mut grid_x = vec![vec![0.0; cols]; rows];

    for i in 0..rows {
        for j in 0..cols {
            grid_x[i][j] = x[j]; // Fill grid_x with x values
            grid_y[i][j] = y[i]; // Fill grid_y with y values
        }
    }

    (grid_x, grid_y)
}